"""Explain generic atomic64 storage, hashed locks, cache layout and snapshots."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1533': ('큰 숫자를 두 장의 종이에 나누어 적는다고 해 봅시다. 친구가 고치는 중에 앞장만 새것, 뒷장은 옛것을 읽으면 원래 없던 숫자를 볼 수 있습니다. 읽기와 고치기가 서로 끼어들지 않게 하는 규칙이 필요합니다.', '64비트 저장 공간과 원자적으로 다루는 방법을 구별합니다.', 'atomic64_t 상자 안에 s64 counter를 적고, 읽기와 고치기 화살표 양쪽에 같은 잠금을 그리세요. 큰 자료형만 선언하는 것과 보호된 연산을 구별하세요.', ['atomic64_t는 64비트 정수를 원자 연산 API로 다루는 자료형입니다. 원자적이라는 말은 다른 참여 연산이 중간에 끼어들어 쪼개진 결과를 보지 않도록 하나의 연산으로 다룬다는 뜻입니다. 반드시 CPU 명령 하나만 실행한다는 뜻은 아닙니다.', '이 generic 헤더의 실제 저장 구조는 s64 counter 하나입니다. s64는 부호 있는 64비트 정수, 즉 음수와 양수를 담을 수 있는 형식입니다. 구조체의 크기와 접근을 보호하는 방법은 별개입니다.', 'ATOMIC64_INIT(i)는 처음 값을 넣는 초기화 표현입니다. 예를 들어 i가 7이면 counter를 7로 시작합니다. 이미 다른 작업이 사용 중인 값을 마음대로 다시 초기화해도 안전하게 해 주는 잠금 명령은 아닙니다.', '어떤 CPU에는 필요한 64비트 원자 명령이 없습니다. lib/atomic64.c의 generic 구현은 잠금을 이용해 읽기와 변경을 보호합니다. 잠금을 잡은 연산이 끝나야 같은 잠금을 사용하는 다른 연산이 들어올 수 있도록 하는 방식입니다.', '반대로 다른 CPU 계열은 자체 명령을 활용하는 별도 구현을 쓸 수 있습니다. generic은 여러 환경에 사용할 공통 대체 구현이라는 뜻입니다. 여기서 읽은 소스가 모든 아키텍처의 실행 경로라고 단정하지 않습니다.', 'counter를 직접 읽거나 쓰면 필요한 API의 보호를 건너뛸 수 있습니다. 같은 자료를 함께 쓰는 참여자들이 해당 원자 연산 API를 지켜야 합니다. 자료를 저장할 공간, 읽고 쓰는 동기화 방법, 그 자료가 유효한 기간을 따로 확인하세요.'], [('s64 counter 한 칸을 선언하면 모든 CPU에서 원자 연산이 자동 보장될까요?', ['네. 64비트 자료형이면 항상 원자 CPU 명령이 돼요', '아니요. 이 대체 구현은 잠금으로 접근을 보호해요'], 's64는 담을 값의 형식을 정합니다. CPU가 그 값을 어떻게 읽고 바꾸는지는 별도 문제예요. 이 generic 본문은 잠금을 잡고 counter를 다룹니다.'), ('모든 CPU의 atomic64 연산이 반드시 이 generic 파일을 거치나요?', ['아니요. 아키텍처별로 다른 구현을 사용할 수 있어요', '네. 모든 CPU가 이 파일 하나만 사용해요'], '원문은 64비트 원자 명령이 없는 CPU 등에 쓸 수 있는 공통 구현이라고 설명합니다. 특정 구현의 잠금 방식을 모든 아키텍처로 넓혀 말하면 안 됩니다.')]), 'os1534': ('수많은 사물함에 각각 열쇠 관리자를 두는 대신 관리자 16명에게 나누어 맡긴다고 해 봅시다. 서로 다른 사물함을 같은 관리자가 맡을 수 있지만 사물함 속 물건까지 합쳐지는 것은 아닙니다.', '주소로 공유 잠금을 고르는 방법과 해시 충돌의 뜻을 이해합니다.', '잠금 번호가 0부터 15까지인 칸을 그리세요. 서로 다른 A와 B가 같은 3번을 고르더라도 A의 값과 B의 값은 별도 상자에 적으세요.', ['이 구현에는 NR_LOCKS=16으로 정한 공유 잠금 배열이 있습니다. 배열은 같은 모양의 칸을 줄지어 둔 자료입니다. 모든 atomic64 객체마다 잠금을 하나씩 붙이는 대신 16개 가운데 하나를 골라 씁니다.', 'lock_addr는 객체 v의 메모리 주소를 unsigned long 숫자로 봅니다. 먼저 L1_CACHE_SHIFT만큼 오른쪽으로 이동합니다. 이는 캐시라인 안 위치를 나타내는 낮은 비트 부분을 덜어내는 단계입니다. 비트는 0 또는 1인 숫자 자리입니다.', '그다음 addr ^= (addr >> 8) ^ (addr >> 16)으로 높은 자리 일부를 섞습니다. ^는 XOR로 두 비트가 다르면 1, 같으면 0이 됩니다. 주소 숫자의 일부만 편중해 쓰지 않도록 섞는 해시 계산입니다.', '마지막 addr & (NR_LOCKS - 1)은 15와 비트 AND를 합니다. 아래 네 자리만 남겨 0부터 15 사이 번호를 고릅니다. 이렇게 입력 주소를 작은 번호로 바꾸는 해시가 선택하는 대상은 저장 값이 아니라 잠금입니다.', '같은 객체의 read와 add는 모두 lock_addr(v)를 쓰므로 같은 잠금을 고릅니다. 서로 다른 객체도 같은 번호가 될 수 있습니다. 이를 충돌이라고 합니다. 이때 연산이 같은 잠금을 기다려 차례로 실행되지만 각 객체의 counter는 자기 저장 공간에 따로 남습니다.', '작은 잠금 배열은 잠금용 메모리를 줄이는 대신 불필요한 기다림을 만들 수 있습니다. A와 B의 값은 독립이어도 같은 잠금을 쓰면 동시에 처리하지 못할 수 있기 때문입니다. 충돌이 없다는 보장이나 실제 성능 수치는 이 계산만으로 얻을 수 없습니다.'], [('A와 B가 같은 잠금 번호를 고르면 counter도 한 칸으로 합쳐질까요?', ['네. 해시 충돌이면 값도 같은 메모리가 돼요', '아니요. 값은 별도이고 연산이 같은 잠금을 기다려요'], '해시 결과는 lock 포인터입니다. 실제 읽기·쓰기는 전달받은 각각의 v->counter에 이루어져요. 공유되는 보호 도구와 보호할 자료 자체를 구별하세요.'), ('같은 객체의 read와 add는 어떤 잠금을 쓰나요?', ['같은 주소 계산으로 고른 동일한 잠금이에요', '함수 이름마다 서로 상관없는 잠금이에요'], '두 연산 모두 같은 객체 주소 v로 lock_addr를 부릅니다. 같은 자료를 보호하려면 연산 이름이 달라도 같은 잠금 규칙에 참여해야 합니다.')]), 'os1535': ('서로 다른 학생의 메모가 한 장의 종이에 붙어 있다고 해 봅시다. 각자 자기 메모만 고쳐도 종이 한 장을 계속 주고받아야 한다면 불편합니다. 메모를 떨어뜨려 놓는 것은 이런 불필요한 왕복을 줄이는 방법입니다.', '캐시라인을 분리하는 배치와 같은 잠금을 고르는 충돌을 구별합니다.', '잠금 A와 B를 같은 캐시라인 상자 안에 그린 뒤 서로 다른 상자로 옮겨 그리세요. A를 함께 고른 두 객체의 경쟁은 여전히 남는다고 적으세요.', ['CPU 캐시는 자주 쓸 자료를 가까이 보관하는 작은 저장 공간입니다. 자료를 한 바이트씩 독립적으로만 다루지 않고 캐시라인이라는 묶음 단위로 관리합니다. 묶음의 크기는 환경에 따라 다르므로 항상 64바이트라고 외우지 마세요.', '다른 CPU들이 서로 다른 잠금을 바꿔도 그 잠금들이 같은 캐시라인에 있으면 묶음의 변경을 서로 조정하는 비용이 생길 수 있습니다. 논리적으로는 다른 자료인데 같은 묶음 때문에 영향을 주는 일을 false sharing, 즉 거짓 공유라고 부릅니다.', '이 배열의 원소는 raw_spinlock_t lock과 char pad[L1_CACHE_BYTES]가 들어 있는 union입니다. union은 멤버가 같은 저장 공간을 겹쳐 쓰는 C 형식입니다. 두 크기를 단순히 더하는 struct와 다릅니다. pad는 원소에 충분한 공간을 마련하는 역할입니다.', '__cacheline_aligned_in_smp라는 정렬 지정과 원소 크기를 이용해 각 잠금이 별도 캐시라인에 놓이도록 합니다. 정렬은 자료 시작 위치를 정해진 경계에 맞추는 것입니다. pad라는 문자를 처리하거나 복사하는 알고리즘이 아닙니다.', '이 배치는 서로 다른 잠금 사이의 거짓 공유를 줄이려는 것입니다. 하지만 주소 해시가 A와 B라는 두 객체를 똑같은 잠금으로 보냈다면 둘은 여전히 그 잠금을 두고 경쟁합니다. 저장 배치 개선이 해시 충돌을 없애 주지는 않습니다.', '잠금 사이 주소 간격을 확인하면 배치가 의도대로인지 살필 수 있습니다. 그것만으로 실제 CPU에서 몇 퍼센트 빨라졌다고 증명하지는 못합니다. 성능은 어떤 CPU에서 어떤 작업을 얼마나 동시에 실행했는지와 함께 측정해야 합니다.'], [('잠금 사이 공간을 띄우는 padding의 목적은?', ['모든 주소 해시 충돌을 완전히 없애는 것이에요', '다른 잠금들이 같은 캐시라인을 공유하는 비용을 줄이는 것이에요'], '원소를 분리해 거짓 공유를 줄이려는 배치입니다. 두 객체가 같은 잠금 번호를 고르는 해시 계산은 그대로이므로 모든 충돌을 없애지는 못해요.'), ('잠금 사이 주소 간격만 확인하면 모든 CPU의 성능 향상까지 알 수 있나요?', ['아니요. 배치 확인과 실제 성능 측정은 달라요', '네. 간격만 맞으면 모든 작업의 속도가 증명돼요'], '간격 검사는 어디에 놓였는지 확인합니다. 실제 캐시와 경쟁 비용은 CPU와 작업 조건에 따라 달라요. 배치 결과를 측정하지 않은 속도 수치로 바꾸어 말할 수 없습니다.')]), 'os1536': ('게시판의 숫자 7을 수첩에 옮겨 적었다고 해 봅시다. 이후 누군가 게시판을 8로 바꿔도 내 수첩은 저절로 바뀌지 않습니다. 안전하게 읽은 값도 “그때의 값”입니다.', '잠금 아래 읽은 값과 계속 변하는 원본을 구별합니다.', 'A 읽기 0 → B 읽기 0 → A가 1 쓰기 → B가 1 쓰기를 그리세요. 두 번 증가하려 했지만 결과가 1인 이유를 설명하세요.', ['generic_atomic64_read는 먼저 lock_addr(v)로 객체를 보호할 잠금을 찾습니다. 읽기만 하는 함수라도 잠금이 필요합니다. 이 대체 구현에서는 다른 작업의 갱신과 64비트 읽기가 서로 섞이지 않도록 보호해야 하기 때문입니다.', 'raw_spin_lock_irqsave로 잠금을 잡고 인터럽트의 이전 상태를 저장합니다. 그 안에서 val = v->counter로 값을 지역 변수에 복사합니다. 지역 변수 val은 읽은 결과를 담는 별도 칸입니다.', '그다음 raw_spin_unlock_irqrestore로 잠금을 풀고 이전 인터럽트 상태를 되돌린 뒤 val을 반환합니다. 원본은 이후 다른 작업이 바꿀 수 있습니다. 반환값은 보호 구간에서 읽은 스냅샷, 즉 그때의 복사본입니다.', '읽은 뒤 계속 원본을 예약하는 효과는 없습니다. A가 7을 받아 온 직후 B가 원본을 8로 바꾸면 A의 값은 7, 원본은 8일 수 있습니다. 이는 안전한 읽기와 모순되지 않습니다. 읽기 뒤에는 잠금이 이미 풀렸기 때문입니다.', '따라서 read 뒤 set으로 1을 더하는 두 호출 전체를 원자적인 증가로 생각하면 안 됩니다. 시작 값 0에서 A와 B가 각각 0을 읽고 둘 다 1을 쓰면 최종값은 1입니다. 각 읽기와 쓰기가 안전해도 그 사이에 다른 작업이 끼어들 수 있습니다.', '두 번 더한 결과 2가 필요하면 더하기 자체를 하나의 보호 연산으로 하는 add 또는 fetch_add 같은 API를 사용해야 합니다. 함수 하나의 보호 범위와 여러 함수의 조합 범위는 다릅니다. 이름에 atomic이 있다는 이유로 바깥의 모든 계산까지 자동으로 보호되지는 않습니다.'], [('read가 7을 돌려준 뒤 그 값은 계속 원본의 최신 값으로 유지되나요?', ['네. 다른 CPU가 원본을 바꾸지 못하도록 예약해요', '아니요. 잠금 안에서 읽은 그때의 복사본이에요'], '값을 복사한 뒤 잠금을 풀고 반환합니다. 다른 작업은 원본을 바꿀 수 있고 이미 받은 7은 자동 갱신되지 않아요. 관측과 예약을 구별하세요.'), ('각 read와 set이 원자적이면 read 후 set으로 만든 증가 전체도 원자적일까요?', ['아니요. 두 호출 사이에 다른 작업이 끼어들 수 있어요', '네. 원자 함수 두 개를 이어 붙이면 언제나 한 연산이에요'], '두 작업이 0을 각각 읽어 모두 1을 쓰면 두 번 증가하려 해도 결과는 1입니다. 증가 전체를 보호하는 add 계열을 써야 이 사이 끼어들기로 갱신을 잃는 일을 막을 수 있습니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_379.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
